import math
from collections.abc import Sequence
from numbers import Real


def _number(value):
    return isinstance(value, Real) and not isinstance(value, bool) and math.isfinite(value)


def polynomial_families_match(left, right, samples, tolerance=1e-9):
    if not _number(tolerance) or tolerance < 0:
        return False
    if not isinstance(left, Sequence) or isinstance(left, (str, bytes)):
        return False
    if not isinstance(right, Sequence) or isinstance(right, (str, bytes)):
        return False
    if not isinstance(samples, Sequence) or isinstance(samples, (str, bytes)):
        return False

    points = []
    for point in samples:
        if not _number(point):
            return False
        points.append(float(point))

    def validate_family(family):
        result = []
        for polynomial in family:
            if not isinstance(polynomial, Sequence) or isinstance(polynomial, (str, bytes)) or not polynomial:
                return None
            coefficients = []
            for coefficient in polynomial:
                if not _number(coefficient):
                    return None
                coefficients.append(float(coefficient))
            result.append(coefficients)
        return result

    left_copy = validate_family(left)
    right_copy = validate_family(right)
    if left_copy is None or right_copy is None:
        return False

    for first, second in zip(left_copy, right_copy):
        for point in points:
            first_value = 0.0
            second_value = 0.0
            for coefficient in reversed(first):
                first_value = first_value * point + coefficient
            for coefficient in reversed(second):
                second_value = second_value * point + coefficient
            if not math.isfinite(first_value) or not math.isfinite(second_value):
                return False
            if abs(first_value - second_value) > tolerance:
                return False
    return True

